"""Every rounding rule of meterbill, in one place (see docs/rounding.md).

Decimal rounding is done on exact integers, so nothing here depends on the
decimal context.
"""

from __future__ import annotations

import math
from decimal import Decimal

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _int(d: Decimal) -> int:
    return int("".join(map(str, d.as_tuple().digits)))


def _build(negative: bool, magnitude: int, exp: int) -> Decimal:
    return Decimal((1 if negative else 0, tuple(int(c) for c in str(magnitude)), exp))


def _count(value: Decimal, step: Decimal, method: str) -> int:
    """How many steps, as a magnitude, `value` rounds to."""
    shift = value.as_tuple().exponent - step.as_tuple().exponent
    num, den = _int(value), _int(step)
    if shift >= 0:
        num *= 10 ** shift
    else:
        den *= 10 ** -shift
    q, r = divmod(num, den)
    if method == HALF_UP:
        q += 2 * r >= den
    elif method == HALF_EVEN:
        q += 2 * r > den or (2 * r == den and q % 2 == 1)
    return q


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    q = _count(value, step, method)
    return _build(value.is_signed(), q * _int(step), step.as_tuple().exponent)


# A signed count of steps; the flag tells a negative zero from a zero.
def _add(a, b):
    return (a[0] + b[0], a[0] == 0 and b[0] == 0 and a[1] and b[1])


def _neg(a):
    return (-a[0], a[0] == 0 and not a[1])


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """Cut each amount down to `step`; the loss against the rounded sum goes on
    the last amount that is not zero."""
    for a in amounts:
        _check(a, step, DOWN)
    _check(Decimal(0), step, DOWN)
    if not amounts:
        return []
    exp = min(a.as_tuple().exponent for a in amounts)
    total = sum((-1 if a.is_signed() else 1) * _int(a) * 10 ** (a.as_tuple().exponent - exp) for a in amounts)
    whole_value = _build(total < 0, abs(total), exp)
    q = _count(whole_value, step, HALF_UP)
    whole = (-q if total < 0 else q, total < 0)
    parts = []
    for a in amounts:
        q = _count(a, step, DOWN)
        parts.append((-q if a.is_signed() else q, a.is_signed()))
    acc = (0, False)
    for p in parts:
        acc = _add(acc, p)
    rest = _add(whole, _neg(acc))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    s, e = _int(step), step.as_tuple().exponent
    return [_build(c < 0 or (c == 0 and z), abs(c) * s, e) for c, z in parts]


def legacy_cents(value: float, places: int = 2) -> float:
    scale = 10 ** places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if isinstance(value, Decimal):
        if places < 0:
            raise ValueError("places must not be negative")
        if method not in _METHODS:
            raise ValueError(f"unknown rounding method {method!r}")
        if not value.is_finite():
            return format(value, "f")
        step = Decimal((0, (1,), -places))
        return format(round_amount(value, step, method), "f")
    if method != HALF_EVEN:
        raise ValueError("a float is always rounded half to even")
    return format(value, f".{places}f")
EOF

